mapper.update:
UPDATE medical_record
chief_complaint = #{chiefComplaint}, present_illness = #{presentIllness}, physical_exam = #{physicalExam}, diagnosis = #{diagnosis}, doctor_advice = #{doctorAdvice}, remark = #{remark},
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM medical_record mr
    LEFT JOIN patient_user_info pi ON mr.patient_id = pi.id
    LEFT JOIN doctor d ON mr.doctor_id = d.id
WHERE 1 = 1

    AND mr.patient_id = #{patientId}


    AND mr.doctor_id = #{doctorId}


    AND mr.registration_id = #{registrationId}

SELECT mr.id AS id, mr.uuid AS uuid, mr.chief_complaint AS chiefComplaint, mr.diagnosis AS diagnosis, mr.doctor_advice AS doctorAdvice, mr.create_time AS createTime, pi.name AS patientName, d.name AS doctorName FROM medical_record mr LEFT JOIN patient_user_info pi ON mr.patient_id = pi.id LEFT JOIN doctor d ON mr.doctor_id = d.id WHERE 1 = 1
AND mr.patient_id = #{patientId}
AND mr.doctor_id = #{doctorId}
AND mr.registration_id = #{registrationId}
ORDER BY mr.create_time DESC LIMIT #{start}, #{length}

SELECT mrd.id AS id, mrd.chief_complaint AS chiefComplaint, mrd.present_illness AS presentIllness, mrd.physical_exam AS physicalExam, mrd.diagnosis AS diagnosis, mrd.doctor_advice AS doctorAdvice, mrd.remark AS remark, mrd.create_time AS createTime, mr.id AS registrationId, mr.date AS date, mr.slot AS slot, mr.status AS status, md.name AS deptName, d.name AS doctorName FROM medical_record mrd LEFT JOIN medical_registration mr ON mrd.registration_id = mr.id LEFT JOIN doctor d ON mrd.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mrd.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id WHERE mrd.patient_id = #{patientId}
AND mrd.dept_sub_id = #{deptSubId}
AND mrd.doctor_id = #{doctorId}
ORDER BY mr.date DESC, mr.slot DESC
